#!/usr/bin/env tsx

import fs from 'node:fs/promises';
import path from 'node:path';

import { loadSilverStructuredKoreanAliasSourceRows } from './lib/structured-korean-alias-source.js';

const OUTPUT_PATH = path.resolve(
  process.cwd(),
  'src/domain/attribute/service/generated/silver-korean-entity-alias-catalog.ts',
);
const WHITESPACE_RE = /\s+/gu;
const GENERATED_CONFIDENCE = 0.93;
const GENERATED_HEADER = `/**
 * Generated by scripts/generate-silver-korean-entity-alias-catalog.ts.
 *
 * Source: data/silver-phase2-test.ndjson
 * Contract:
 * - Hangul-containing aliases only from structured identitySafeProjection
 * - unique normalized surface -> single silver entity
 * - exact identity aliases only
 * - exportToDefaultMappings=false so wine-SKU labels never leak into
 *   structured planner constraints
 */

export interface SilverKoreanEntityAliasCatalogEntry {
  readonly surface: string;
  readonly mappedAttribute: 'appellation';
  readonly canonicalValue: string;
  readonly mappingConfidence: number;
  readonly provenance: 'silver_catalog';
  readonly resolutionMode: 'direct';
  readonly exportToDefaultMappings: false;
}

export const SILVER_KOREAN_ENTITY_ALIAS_CATALOG: readonly SilverKoreanEntityAliasCatalogEntry[] = [
`;
const GENERATED_FOOTER = `] as const;
`;

interface AliasOwner {
  readonly surface: string;
  readonly canonicalValue: string;
  readonly entityId: string;
}

function normalizeSurface(surface: string): string {
  return surface.normalize('NFKC').toLowerCase().replace(WHITESPACE_RE, ' ').trim();
}

async function run(): Promise<void> {
  const rows = await loadSilverStructuredKoreanAliasSourceRows();
  const owners = new Map<string, AliasOwner[]>();

  for (const row of rows) {
    const canonicalValue = row.canonicalLabel.trim();
    if (canonicalValue.length === 0) {
      continue;
    }

    for (const alias of row.koreanAliases) {
      const surface = alias.trim();
      if (surface.length === 0) {
        continue;
      }

      const normalized = normalizeSurface(surface);
      const existing = owners.get(normalized) ?? [];
      existing.push({
        surface,
        canonicalValue,
        entityId: row.entityId,
      });
      owners.set(normalized, existing);
    }
  }

  const uniqueEntries = [...owners.values()]
    .map((aliasOwners) => {
      const entityIds = [...new Set(aliasOwners.map((entry) => entry.entityId))];
      if (entityIds.length !== 1) {
        return null;
      }
      return aliasOwners[0] ?? null;
    })
    .filter((entry): entry is AliasOwner => entry !== null)
    .sort((left, right) => {
      const byCanonical = left.canonicalValue.localeCompare(right.canonicalValue, 'en');
      if (byCanonical !== 0) {
        return byCanonical;
      }
      return left.surface.localeCompare(right.surface, 'ko');
    });

  const lines = uniqueEntries.map((entry) =>
    `  { surface: ${JSON.stringify(entry.surface)}, mappedAttribute: 'appellation', canonicalValue: ${JSON.stringify(entry.canonicalValue)}, mappingConfidence: ${GENERATED_CONFIDENCE}, provenance: 'silver_catalog', resolutionMode: 'direct', exportToDefaultMappings: false },`,
  );

  const content = `${GENERATED_HEADER}${lines.join('\n')}\n${GENERATED_FOOTER}`;
  await fs.mkdir(path.dirname(OUTPUT_PATH), { recursive: true });
  await fs.writeFile(OUTPUT_PATH, content, 'utf8');
  console.log(`Wrote ${uniqueEntries.length} silver Korean exact aliases to ${OUTPUT_PATH}`);
}

void run().catch((error: unknown) => {
  const message = error instanceof Error ? error.stack ?? error.message : String(error);
  console.error(message);
  process.exit(1);
});
